function nativeJSON(value){const projected=nativeJSONBytes(value),text=JSON.stringify(value)+'\n';assert.equal(Buffer.byteLength(text),projected,'NATIVE_CANONICAL_PROJECTION');return Buffer.from(text);}
function projectedCDP(value){let upper=1;const ancestors=new Set();function add(n){upper+=n;assert(upper<=65536,'CAUSAL_CDP_ENTRY_PREALLOCATION_CAP');}function visit(v){if(v===null){add(4);return;}if(typeof v==='string'){add(2+6*Buffer.byteLength(v));return;}if(typeof v==='number'||typeof v==='boolean'){add(32);return;}assert(v&&typeof v==='object');assert(!ancestors.has(v));ancestors.add(v);add(2);if(Array.isArray(v)){for(const x of v){add(1);visit(x);}}else for(const[k,x]of Object.entries(v)){if(x===undefined)continue;add(4+6*Buffer.byteLength(k));visit(x);}ancestors.delete(v);}visit(value);return upper;}

async function wholeInputCapture(kind){
 assert.equal(process.env.REWARD_FOCUS_WHOLE_INPUT_AUTHORIZATION,'autonomous-v1-whole-input');assert.equal(process.env.GITHUB_WORKSPACE,ROOT);assert.equal(process.env.GITHUB_JOB,'inputs');assert.equal(process.env.GITHUB_REF,'refs/heads/reward-focus-inputs-private');assert.equal(process.version,'v24.21.0');assert.equal(git('rev-parse','HEAD').toString().trim(),process.env.GITHUB_SHA);assert.equal(Number(process.env.GITHUB_RUN_ATTEMPT),1);assert(['setup','collect','pack','upload'].includes(kind));
 const capacityPath=OUT+'/reward-focus-private-run-capacity.json';if(kind==='setup'){assert(!fs.existsSync(capacityPath));const before=total(),planned=120*1024*1024;assert(before+planned+RESERVE<=CAP);assert(free()>=MIN_FREE+planned);write(capacityPath,JSON.stringify({before,planned,unusedReservation:RESERVE,cap:CAP,free:free(),sha:process.env.GITHUB_SHA,run:Number(process.env.GITHUB_RUN_ID),attempt:1}));}
 const capacity=JSON.parse(read(capacityPath,65536));assert.equal(capacity.sha,process.env.GITHUB_SHA);assert.equal(capacity.run,Number(process.env.GITHUB_RUN_ID));const prefix=kind==='collect'?'reward-focus-private':'reward-focus-private-'+kind,streamNames=['reward-focus-private-setup.stdout','reward-focus-private-setup.stderr','reward-focus-private.stdout','reward-focus-private.stderr','reward-focus-private-pack.stdout','reward-focus-private-pack.stderr'];
 let prior=0;for(const name of streamNames){const file=OUT+'/'+name;if(fs.existsSync(file)){assert(kind!=='setup');assert(!name.startsWith(prefix+'.'));assert.equal(fs.realpathSync(file),file);const st=fs.lstatSync(file);assert(st.isFile()&&!st.isSymbolicLink()&&st.size<=LOG_CAP);prior+=st.size;assert(prior<=LOG_CAP);}}
 const fds=[fs.openSync(OUT+'/'+prefix+'.stdout','wx'),fs.openSync(OUT+'/'+prefix+'.stderr','wx')],counts=[0,0],observations=[];let hold=null,active,escalation;const ownedGroups=new Map();
 const {spawn}=await import('node:child_process');
 function identity(pid){try{const stat=fs.readFileSync('/proc/'+pid+'/stat','utf8');assert(stat.length<=65536);return stat.slice(stat.lastIndexOf(')')+2).split(' ')[19];}catch(e){if(e.code==='ENOENT'||e.code==='ESRCH')return null;throw e;}}
 function snapshot(){if(!active?.pid)return;const rootStart=identity(active.pid);if(rootStart&&!ownedGroups.has(active.pid))ownedGroups.set(active.pid,[{pid:active.pid,start:rootStart}]);const table=execFileSync('ps',['-eo','pid=,ppid=,pgid='],{encoding:'utf8',maxBuffer:1048576}).trim().split('\n').map(l=>l.trim().split(/\s+/).map(Number)),owned=new Set([active.pid]);let changed=true;while(changed){changed=false;for(const[pid,ppid]of table)if(owned.has(ppid)&&!owned.has(pid)){owned.add(pid);changed=true;}}for(const[pid,,group]of table)if(owned.has(pid)){assert(Number.isSafeInteger(group)&&group>0&&group!==process.pid);if(table.filter(r=>r[2]===group).every(r=>owned.has(r[0]))){if(!ownedGroups.has(group))ownedGroups.set(group,[]);const start=identity(pid);if(start)ownedGroups.get(group).push({pid,start});}}}
 function signalOwned(signal){for(const[group,members]of ownedGroups){if(!members.some(m=>identity(m.pid)===m.start))continue;try{process.kill(-group,signal);}catch(e){if(e.code!=='ESRCH')hold.killError=e.message;}}}
 function stop(code){if(hold)return;hold={code,complete:false,fullStreamsAvailable:false};try{snapshot();signalOwned('SIGTERM');}catch(e){hold.killError=e.message;if(active?.pid)try{process.kill(-active.pid,'SIGTERM');}catch{}}escalation=setTimeout(()=>{try{signalOwned('SIGKILL');hold.escalated=true;}catch(e){hold.killError=e.message;}},5000);}
 const timer=setTimeout(()=>stop('DIAGNOSTIC_CAPTURE_TIMEOUT'),kind==='collect'?1200000:600000);
 function retain(which,b){if(hold)return;try{const bytes=counts[0]+counts[1]+prior+b.length;if(bytes>LOG_CAP||total()+b.length+RESERVE>CAP||total()+b.length>capacity.before+capacity.planned||free()<MIN_FREE+b.length){stop('DIAGNOSTIC_CAPTURE_CAP_REFUSAL');hold.rejectedChunkBytes=b.length;return;}let at=0;while(at<b.length){const n=fs.writeSync(fds[which],b,at,b.length-at);assert(n>0);at+=n;}counts[which]+=b.length;}catch(e){stop('DIAGNOSTIC_CAPTURE_WRITE_HOLD');hold.message=e.message;}}
 async function run(args){return await new Promise((resolve,reject)=>{active=spawn(args[0],args.slice(1),{cwd:ROOT,env:process.env,stdio:['ignore','pipe','pipe'],detached:true});active.stdout.on('data',b=>retain(0,b));active.stderr.on('data',b=>retain(1,b));active.once('error',reject);active.once('close',(code,signal)=>{observations.push({command:args[0],exitCode:code,signal});active=undefined;resolve(code);});});}
 let failed;try{const commands=kind==='setup'?[[process.execPath,'--version'],['npm','ci'],[process.execPath,'-e',"const fs=require('node:fs');const p=JSON.parse(fs.readFileSync('node_modules/playwright/package.json'));if(p.version!=='1.63.0')throw Error('Playwright version mismatch');console.log('PLAYWRIGHT '+p.version)"]]:[[process.execPath,ROOT+'/tools/test-reward-focus-private.mjs',kind==='collect'?'--whole-input-collect':kind==='pack'?'--whole-input-pack':'--whole-input-upload-admit']];for(const command of commands){const code=await run(command);if(code!==0||hold){failed=code??1;break;}}}catch(e){stop('DIAGNOSTIC_CAPTURE_ERROR');hold.message=e.message;failed=1;}finally{clearTimeout(timer);if(escalation){await new Promise(resolve=>setTimeout(resolve,5100));clearTimeout(escalation);try{signalOwned('SIGKILL');}catch(e){hold.killError=e.message;}hold.ownedGroups=Array.from(ownedGroups.keys());hold.remainingOwnedProcesses=Array.from(ownedGroups.values()).flat().filter(m=>identity(m.pid)===m.start).map(m=>m.pid);}for(const fd of fds)fs.closeSync(fd);}
 const record={scope:'BOUNDED_CAPTURE_NOT_ACCEPTANCE',kind,sha:process.env.GITHUB_SHA,run:Number(process.env.GITHUB_RUN_ID),attempt:1,priorBytes:prior,bytes:counts,observations,hold,exitCode:failed||0,complete:!hold};assert(nativeJSONBytes(record)<=65536,'WHOLE_INPUT_CAPTURE_PREALLOCATION_CAP');const raw=nativeJSON(record);assert(raw.length<=65536);assert(total()+raw.length+RESERVE<=CAP&&total()+raw.length<=capacity.before+capacity.planned);write(OUT+'/'+prefix+'-capture.json',raw);console.log('WHOLE INPUT CAPTURE '+JSON.stringify(record));if(failed||hold)process.exitCode=1;
}

function verifyUpload(){assert.equal(process.env.GITHUB_WORKSPACE,ROOT);assert.equal(git('rev-parse','HEAD').toString().trim(),process.env.GITHUB_SHA);const meta=JSON.parse(read(OUT+'/reward-focus-private-envelope-metadata.json',65536)),admission=JSON.parse(read(OUT+'/reward-focus-private-upload-admission.json',65536));assert.equal(meta.sha,process.env.GITHUB_SHA);assert.equal(admission.sha,meta.sha);assert.equal(admission.runId,process.env.GITHUB_RUN_ID);assert.equal(admission.attempt,1);const expected=['reward-focus-private-envelope.cwproof','reward-focus-private-envelope-metadata.json','reward-focus-private-pack.stdout','reward-focus-private-pack.stderr',...["reward-focus-private-setup-capture.json","reward-focus-private-capture.json","reward-focus-private-pack-capture.json","reward-focus-private-run-capacity.json"],...meta.images.map(i=>i.path)];assert.deepEqual(admission.rows.map(r=>r.path),expected);assert.deepEqual(admission.pendingUploadCapture,{path:'reward-focus-private-upload-capture.json',maximumBytes:65536,hash:'NOT_YET_CREATED_REQUIRES_FINAL_VERIFICATION'});const actual=[];for(const row of admission.rows){assert(!row.path.includes('\\')&&!row.path.split('/').includes('..'));const b=read(OUT+'/'+row.path,row.path.endsWith('.png')?524288:row.path.endsWith('.cwproof')?MEMBER_CAP:65536);assert.equal(b.length,row.bytes);assert.equal(hash(b),row.sha256);assert.equal(deflateRawSync(b,{level:6}).length,row.compressedBytes);actual.push({path:row.path,bytes:b.length,sha256:hash(b),compressedBytes:row.compressedBytes});}for(const name of ['reward-focus-private-upload-capture.json','reward-focus-private-upload-admission.json']){const b=read(OUT+'/'+name,65536);actual.push({path:name,bytes:b.length,sha256:hash(b),compressedBytes:deflateRawSync(b,{level:6}).length});}for(const name of [...["reward-focus-private-setup-capture.json","reward-focus-private-capture.json","reward-focus-private-pack-capture.json"],'reward-focus-private-upload-capture.json']){const c=JSON.parse(read(OUT+'/'+name,65536));assert(c.complete&&c.exitCode===0&&!c.hold);assert.deepEqual(c.bytes[1],0);assert.equal(c.sha,meta.sha);assert.equal(c.run,Number(meta.runId));assert.equal(c.attempt,1);assert(c.observations.every(o=>o.exitCode===0&&o.signal===null));}assert.deepEqual(fs.readdirSync(VIRTUAL+'/.out').filter(n=>n.endsWith('.png')).sort(),meta.images.map(i=>path.basename(i.path)).sort());let upper=22;for(const row of actual)upper+=row.compressedBytes+30+46+2*Buffer.byteLength(row.path);assert(upper<=2097152);assert(upper<=admission.zipUpperIncludingSelfAndHeaderAllowance);admit(0);console.log('PRIVATE FINAL UPLOAD VERIFIED '+JSON.stringify({sha:meta.sha,runId:meta.runId,attempt:1,rows:actual,zipUpper:upper,scope:'COMPLETE_UPLOAD_SELECTION_ONLY_NOT_PRODUCT_ACCEPTANCE'}));}

const mode=process.argv[2];try{if(mode==='--inspect'){const p=decodePayload();console.log(JSON.stringify({status:'PRIVATE_PAYLOAD_CPU_CHECK_ONLY',base:BASE,product:PRODUCT,owned:p.owned,full:p.full.length,raw:PAYLOAD.rawBytes,packed:PAYLOAD.packedBytes}));}else if(mode==='--whole-input-collect')await collect();else if(mode==='--whole-input-pack')await pack();else if(mode==='--whole-input-upload-admit')uploadAdmit();else if(mode==='--whole-input-verify-upload')verifyUpload();else if(mode==='--whole-input-capture')await wholeInputCapture(process.argv[3]);else throw Error('Use only explicitly bounded private whole-input modes');}catch(e){console.error('HOLD '+e.message);process.exitCode=1;}
